const KEY='myplanner.data';
const LEGACY_KEYS=['myplanner.web.v4','myplanner.web.v3','myplanner.web.v2','myplanner_tasks','myplanner'];
function loadPersistedState(){
  let found=null, source=null;
  for(const k of [KEY,...LEGACY_KEYS]){
    try{const raw=localStorage.getItem(k); if(raw){const x=JSON.parse(raw); if(x&&typeof x==='object'){found=x;source=k;break}}}catch(e){}
  }
  if(found && source!==KEY){
    try{localStorage.setItem(KEY,JSON.stringify(found)); localStorage.setItem('myplanner.last_migration',JSON.stringify({from:source,at:new Date().toISOString()}));}catch(e){}
  }
  return found;
}
const praise=['Ты большая молодец!','Готово — ещё один шаг!','Отличная работа!','Так держать!','Ты справилась!','Маленькая победа — тоже победа!','План выполнен — умница!','Ещё один пункт закрыт!','Вот это продуктивность!','Ты двигаешься вперёд!','Можно выдохнуть — дело закрыто!','Красиво выполнено!'];
const repeatOptions=['Не повторять','Каждые 5 минут','Каждые 15 минут','Каждые 30 минут','Каждый час','Каждый день','Каждую неделю','Каждый месяц','Каждый год','Произвольный интервал'];
const defaultGroups=[{id:'g1',name:'Личное',icon:'❤️',color:'#a16bd3',system:true},{id:'g2',name:'Работа',icon:'💼',color:'#5b7cfa',system:true},{id:'g3',name:'Дом',icon:'🏠',color:'#58a66a',system:true},{id:'g4',name:'Семья',icon:'👨‍👩‍👧‍👦',color:'#d95f7a',system:true}];
const defaultSettings={sound:true,defaultReminderOffset:'10m',defaultSound:'standard',focusHorizon:3,focusLimit:3,focusPreviewHour:19,theme:'system',background:{type:'solid',value:'#f5f7fb'},cardStyle:'comfortable'};
const old=loadPersistedState();
let state=old&&typeof old==='object'?old:{tasks:[],groups:[],notes:[],events:[],focusIds:[],focusRules:{},view:'day',date:iso(new Date()),query:'',filter:'all',group:'all',statsPeriod:'today',settings:defaultSettings};
state.tasks=Array.isArray(state.tasks)?state.tasks:[];state.groups=Array.isArray(state.groups)?state.groups:[];state.notes=Array.isArray(state.notes)?state.notes:[];state.events=Array.isArray(state.events)?state.events:[];state.focusIds=Array.isArray(state.focusIds)?state.focusIds:[];state.focusRules=state.focusRules||{};state.settings={...defaultSettings,...(state.settings||{}),background:{...defaultSettings.background,...((state.settings||{}).background||{})}};
defaultGroups.forEach(g=>{if(!state.groups.some(x=>x.name===g.name))state.groups.push({...g})});
state.tasks.forEach(t=>{if(t.reminder===undefined)t.reminder=false;if(t.reminderSound===undefined)t.reminderSound=true;if(t.reminderOffset===undefined)t.reminderOffset=state.settings.defaultReminderOffset;if(t.sound===undefined)t.sound=state.settings.defaultSound;if(t.comment===undefined)t.comment=t.notes||'';if(t.done===undefined)t.done=false;if(t.allDay===undefined)t.allDay=false;if(t.repeat===undefined)t.repeat='Не повторять';if(t.important===undefined)t.important=false;if(t.priority===undefined)t.priority='Средний';if(t.interval===undefined)t.interval=1;if(t.unit===undefined)t.unit='days'});
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){console.error('MyPlanner save failed',e)}} function uid(){return Math.random().toString(36).slice(2)+Date.now().toString(36)} function iso(d){return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10)} function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))} function fmtDate(s){return new Date(s+'T12:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'})} function parseDate(s){return new Date(s+'T12:00')}
function app(){document.body.dataset.theme=state.settings.theme;applyBackground();document.querySelector('#app').innerHTML=`<main class="app"><header class="top"><div class="topline"><div class="topnav">${[['roulette','Рулетка'],['notes','Заметки'],['stats','Статистика'],['settings','Настройки']].map(x=>`<button class="${state.view===x[0]?'active':''}" onclick="setView('${x[0]}')">${x[1]}</button>`).join('')}</div></div><div class="viewline"><div class="viewnav">${[['day','День'],['week','Неделя'],['month','Месяц'],['focus','Фокус']].map(x=>`<button class="${state.view===x[0]?'active':''}" onclick="setView('${x[0]}')">${x[1]}</button>`).join('')}</div></div></header>${renderView()}<button class="fab" onclick="editTask()">+</button><div id="praise"></div></main>`;startReminderWatcher()}
function setView(v){if(state.view==='week'){state.weekOpenDates=[...document.querySelectorAll('.week-day[open]')].map(e=>e.dataset.weekDate)}state.view=v;save();app()} function renderView(){if(state.view==='notes'&&state.noteOpen)return noteBrowser();return ({day,week,month,focus,stats,notes,settings,roulette}[state.view]||day)()}
function tasksForDate(s){return state.tasks.filter(t=>t.date===s)}
function filteredTasks(){return tasksForDate(state.date).filter(t=>state.group==='all'||t.groupId===state.group).filter(t=>!state.query||t.title.toLowerCase().includes(state.query.toLowerCase())).filter(t=>state.filter==='all'||state.filter==='done'&&t.done||state.filter==='important'&&t.important||state.filter==='active'&&!t.done).sort((a,b)=>(a.allDay?0:1)-(b.allDay?0:1)||(a.time||'99:99').localeCompare(b.time||'99:99'))}
function groupButtons(){return `<button class="${state.group==='all'?'primary':''}" onclick="state.group='all';app()">Все</button>`+state.groups.map(g=>`<button class="${state.group===g.id?'primary':''}" onclick="state.group='${g.id}';app()">${g.icon} ${esc(g.name)}</button>`).join('')}
function taskCard(t,compact=false){const g=state.groups.find(x=>x.id===t.groupId);return `<article class="card task-card ${compact?'compact':''}" data-task-id="${t.id}" style="background:${t.color||g?.color||'#ffffff'}"><div class="task"><button class="check ${t.done?'done':''}" onclick="toggle('${t.id}')">${t.done?'✓':''}</button><div class="taskmain" onclick="editTask('${t.id}')"><div class="tasktitle">${esc(t.title)}</div><div class="meta">${t.allDay?'<span class="pill time-pill">📌 Весь день</span>':t.time?`<span class="pill time-pill">⏰ ${t.time}</span>`:''}${!compact&&t.important?'<span class="pill">⭐ Важное</span>':''}${!compact&&t.priority?`<span class="pill">${esc(t.priority)}</span>`:''}${g?`<span class="pill group-pill">${g.icon} ${esc(g.name)}</span>`:''}${!compact&&t.repeat&&t.repeat!=='Не повторять'?`<span class="pill">🔁 ${esc(t.repeat)}</span>`:''}${!compact&&t.reminder?`<span class="pill">${t.reminderSound?'🔔':'🔕'} ${displayReminderTime(t)}</span>`:''}${t.comment?`<span class="pill">💬 ${esc(t.comment.slice(0,38))}${t.comment.length>38?'…':''}</span>`:''}</div></div><button class="task-delete" aria-label="Удалить задачу" title="Удалить" onclick="event.stopPropagation();quickDeleteTask('${t.id}')">🗑️</button></div></article>`}
function day(){const ts=filteredTasks();return `<section class="card day-controls"><div class="day-nav"><button class="date-arrow" onclick="shift(-1)" aria-label="Предыдущий день">‹</button><b>${fmtDate(state.date)}</b><button class="date-arrow" onclick="shift(1)" aria-label="Следующий день">›</button></div><div class="filter-row">${['all','active','important','done'].map(f=>`<button class="filter-btn ${state.filter===f?'selected':''}" onclick="state.filter='${f}';app()">${({all:'Все',active:'Активные',important:'Важные',done:'Готово'})[f]}</button>`).join('')}</div><div class="group-filter-row">${groupButtons()}</div></section>${ts.length?ts.map(t=>taskCard(t)).join(''):'<div class="empty">На этот день дел пока нет.<br>Нажми + и добавь первое.</div>'}`}
function sortTasks(list){const mode=state.settings.taskSort||'time';return list.slice().sort((a,b)=>{if(mode==='name')return (a.title||'').localeCompare(b.title||'','ru');if(mode==='group')return ((state.groups.find(g=>g.id===a.groupId)?.name||'').localeCompare(state.groups.find(g=>g.id===b.groupId)?.name||'','ru'))||(a.time||'99:99').localeCompare(b.time||'99:99');return (a.allDay?0:1)-(b.allDay?0:1)||(a.time||'99:99').localeCompare(b.time||'99:99')})}
function sortControl(){return `<div class="field"><label>Сортировка задач</label><select class="input" onchange="saveWeekOpenAndSort(this.value)"><option value="time" ${(state.settings.taskSort||'time')==='time'?'selected':''}>По времени</option><option value="name" ${state.settings.taskSort==='name'?'selected':''}>По названию А–Я</option><option value="group" ${state.settings.taskSort==='group'?'selected':''}>По группам</option></select></div>`}
function saveWeekOpenAndSort(value){state.weekOpenDates=[...document.querySelectorAll('.week-day[open]')].map(e=>e.dataset.weekDate);state.settings.taskSort=value;save();app()}
function week(){let d=new Date();d.setHours(12,0,0,0);let h='';for(let i=0;i<7;i++){let x=new Date(d);x.setDate(d.getDate()+i);let date=iso(x),ts=tasksForDate(date).filter(t=>!t.done);h+=`<details class="card week-day" data-week-date="${date}" ${state.weekOpenDates?.includes(date)?'open':''}><summary><b>${x.toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'})}</b><span class="small">${ts.length} дел</span></summary><div class="week-items">${sortTasks(ts).map(t=>taskCard(t,true)).join('')||'<div class="small">Нет активных дел</div>'}<button onclick="state.date='${date}';state.view='day';app()">Открыть день</button></div></details>`}return sortControl()+h}
function month(){let d=parseDate(state.date),y=d.getFullYear(),m=d.getMonth(),first=new Date(y,m,1),start=(first.getDay()+6)%7,days=new Date(y,m+1,0).getDate();let h=`<section class="card"><div class="between"><button onclick="monthShift(-1)">←</button><b>${d.toLocaleDateString('ru-RU',{month:'long',year:'numeric'})}</b><button onclick="monthShift(1)">→</button></div><div class="calendar">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(x=>`<div class="calhead">${x}</div>`).join('')}`;for(let i=0;i<start;i++)h+='<div></div>';for(let n=1;n<=days;n++){let s=iso(new Date(y,m,n)),ts=tasksForDate(s);h+=`<div class="day ${s===state.date?'sel':''}" onclick="state.date='${s}';state.view='day';app()"><b>${n}</b><div>${ts.slice(0,5).map(t=>`<span class="dot" style="background:${t.color||'#5b7cfa'}"></span>`).join('')}</div></div>`}return h+'</div></section>'}
function shift(n){let d=parseDate(state.date);d.setDate(d.getDate()+n);state.date=iso(d);save();app()} function monthShift(n){let d=parseDate(state.date);d.setMonth(d.getMonth()+n,1);state.date=iso(d);save();app()}
function baseTask(){return{id:uid(),title:'',date:state.date,time:'',allDay:false,done:false,important:false,priority:'Средний',groupId:state.groups[0]?.id||'',repeat:'Не повторять',interval:1,unit:'days',comment:'',reminder:false,reminderSound:true,reminderOffset:state.settings.defaultReminderOffset,reminderTime:'',sound:state.settings.defaultSound,seriesId:null,focus:false}}
function editTask(id){const old=state.tasks.find(x=>x.id===id),t=old?{...old}:baseTask(),fresh=!old;modal(`<div class="between"><h2>${fresh?'Новое дело':'Редактировать дело'}</h2><button onclick="closeModal()">✕</button></div><div class="field"><label>Название</label><input id="etitle" class="input" value="${esc(t.title)}"></div><div class="grid"><div class="field"><label>Дата</label><input id="edate" class="input" type="date" value="${t.date}"></div><div class="field" id="taskTimeField" style="display:${t.allDay?'none':'block'}"><label>Время</label><input id="etime" class="input" type="time" value="${t.time||''}"></div></div><div class="field"><label><input id="eall" type="checkbox" ${t.allDay?'checked':''} onchange="toggleAllDay()"> 📌 Весь день</label></div><div class="grid"><div class="field"><label>Группа</label><select id="egroup" class="input">${state.groups.map(g=>`<option value="${g.id}" ${g.id===t.groupId?'selected':''}>${g.icon} ${esc(g.name)}</option>`).join('')}</select></div><div class="field"><label>Приоритет</label><select id="eprio" class="input">${['Низкий','Средний','Высокий'].map(x=>`<option ${x===t.priority?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="field color-field"><div class="color-field-line"><label for="etcolor">Цвет задачи</label><input id="etcolor" type="color" value="${t.color||state.groups.find(g=>g.id===t.groupId)?.color||'#ffffff'}" oninput="this.nextElementSibling.style.background=this.value"><span class="color-preview" style="background:${t.color||state.groups.find(g=>g.id===t.groupId)?.color||'#ffffff'}"></span></div></div><div class="field"><label><input id="eimp" type="checkbox" ${t.important?'checked':''}> ⭐ Важное</label></div><div class="field"><label>Повтор</label><select id="erepeat" class="input" onchange="toggleRepeatFields()">${repeatOptions.map(x=>`<option ${x===t.repeat?'selected':''}>${x}</option>`).join('')}</select></div><div class="grid" id="custom" style="display:${t.repeat==='Произвольный интервал'?'grid':'none'}"><div class="field"><label>Каждые</label><input id="einterval" class="input" type="number" min="1" value="${t.interval||1}"></div><div class="field"><label>Единица</label><select id="eunit" class="input"><option value="minutes" ${t.unit==='minutes'?'selected':''}>минут</option><option value="hours" ${t.unit==='hours'?'selected':''}>часов</option><option value="days" ${t.unit==='days'?'selected':''}>дней</option><option value="weeks" ${t.unit==='weeks'?'selected':''}>недель</option><option value="months" ${t.unit==='months'?'selected':''}>месяцев</option></select></div></div><div class="field"><label><input id="efocus" type="checkbox" ${t.focus||state.focusIds.includes(t.id)?'checked':''} onchange="toggleFocusChoice()"> 🎯 В Фокус</label><div id="focusChoice" style="display:${(t.focus||state.focusIds.includes(t.id))&&t.repeat!=='Не повторять'?'block':'none'};margin-top:8px"><div class="small" style="margin-bottom:6px">Добавить в Фокус:</div><label><input type="radio" name="focusMode" value="single" ${state.focusRules[t.seriesId||t.id]?.mode==='single'||(!state.focusRules[t.seriesId||t.id]&&t.focus)?'checked':''}> Только эту задачу</label><br><label><input type="radio" name="focusMode" value="future" ${state.focusRules[t.seriesId||t.id]?.mode==='future'?'checked':''}> Эту и все будущие повторы</label></div></div><div class="card reminder-box"><label><input id="erem" type="checkbox" ${t.reminder?'checked':''} onchange="toggleReminderFields()"> 🔔 Напоминание</label><div id="remFields" style="display:${t.reminder?'block':'none'}"><div class="grid"><div class="field"><label>Когда напомнить</label><select id="eremoffset" class="input" onchange="toggleReminderTime()"><option value="alltime">Выбрать время</option><option value="at">В момент дела</option><option value="5m">За 5 минут</option><option value="10m">За 10 минут</option><option value="15m">За 15 минут</option><option value="30m">За 30 минут</option><option value="1h">За 1 час</option><option value="2h">За 2 часа</option><option value="1d">За 1 день</option><option value="manual">Вручную</option></select></div><div class="field" id="remManualTime" style="display:none"><label>Время напоминания</label><input id="eremtime" class="input" type="time" value="${t.reminderTime||''}"></div><div class="grid"><div class="field"><label>Режим</label><select id="ersound" class="input"><option value="sound" ${t.reminderSound!==false?'selected':''}>🔔 Со звуком</option><option value="silent" ${t.reminderSound===false?'selected':''}>🔕 Без звука</option></select></div><div class="field"><label>🎵 Мелодия</label><select id="esound" class="input"><option value="standard">Стандартная</option><option value="soft">Мягкая</option><option value="bell">Колокольчик</option><option value="chime">Звонок</option><option value="pulse">Короткий сигнал</option></select><button type="button" onclick="previewSound(document.querySelector('#esound').value)">▶ Прослушать</button></div></div></div></div><div class="field"><label>Комментарий</label><textarea id="ecomment" rows="3">${esc(t.comment||'')}</textarea></div><div class="toolbar"><button class="primary" onclick="saveTask('${t.id}',${fresh})">Сохранить</button>${!fresh?`<button class="danger" onclick="quickDeleteTask('${t.id}')">Удалить</button>`:''}</div>`);const remSel=document.querySelector('#eremoffset');if(t.allDay){remSel.value=(t.reminderOffset==='manual'?'manual':'alltime');const rt=document.querySelector('#eremtime');if(rt&&!rt.value)rt.value=t.reminderTime||'08:00';}else{remSel.value=t.reminderOffset||state.settings.defaultReminderOffset;}document.querySelector('#esound').value=t.sound||state.settings.defaultSound;toggleReminderTime()}

function setReminderOptions(){
  const sel=document.querySelector('#eremoffset'), all=document.querySelector('#eall')?.checked;
  if(!sel)return;
  const current=sel.value;
  const allDay=[['alltime','08:00'],['all09','09:00'],['all10','10:00'],['all12','12:00'],['all15','15:00'],['all18','18:00'],['all20','20:00'],['manual','Другое время…']];
  const timed=[['at','В момент дела'],['5m','За 5 минут'],['10m','За 10 минут'],['15m','За 15 минут'],['30m','За 30 минут'],['1h','За 1 час'],['2h','За 2 часа'],['1d','За 1 день'],['manual','Вручную']];
  const opts=all?allDay:timed;
  const normalized=all ? (current.startsWith('all')||current==='manual'?current:'alltime') : (current.startsWith('all')?'at':current);
  sel.innerHTML=opts.map(([v,label])=>`<option value="${v}">${label}</option>`).join('');
  sel.value=opts.some(x=>x[0]===normalized)?normalized:(all?'alltime':'at');
  const tm=document.querySelector('#eremtime');
  if(all && tm && !tm.value)tm.value='08:00';
}
function toggleAllDay(){const all=document.querySelector('#eall').checked;document.querySelector('#taskTimeField').style.display=all?'none':'block';if(all){document.querySelector('#etime').value='';const tm=document.querySelector('#eremtime');if(tm&&!tm.value)tm.value='08:00';}setReminderOptions();toggleReminderTime();toggleFocusChoice()}
function toggleRepeatFields(){document.querySelector('#custom').style.display=document.querySelector('#erepeat').value==='Произвольный интервал'?'grid':'none';toggleFocusChoice()}
function toggleReminderFields(){const on=document.querySelector('#erem').checked;document.querySelector('#remFields').style.display=on?'block':'none';if(on){setReminderOptions();toggleReminderTime()}}
function toggleReminderTime(){setReminderOptions();const sel=document.querySelector('#eremoffset'),tm=document.querySelector('#eremtime'),wrap=document.querySelector('#remManualTime'),all=document.querySelector('#eall')?.checked;if(!sel||!tm)return;const allTime=sel.value==='alltime'||sel.value.startsWith('all');const manual=sel.value==='manual';if(wrap)wrap.style.display=(manual||allTime)?'block':'none';tm.disabled=!(manual||allTime);if(allTime){const fixedTimes={alltime:'08:00',all09:'09:00',all10:'10:00',all12:'12:00',all15:'15:00',all18:'18:00',all20:'20:00'};if(fixedTimes[sel.value])tm.value=fixedTimes[sel.value];else if(!tm.value)tm.value='08:00';}if(!all&&!manual&&!allTime&&sel.value!=='at'){const base=document.querySelector('#etime')?.value;if(base){const mins={'5m':5,'10m':10,'15m':15,'30m':30,'1h':60,'2h':120,'1d':1440}[sel.value]||0;let [h,m]=base.split(':').map(Number),v=(h*60+m-mins+1440)%1440;tm.value=String(Math.floor(v/60)).padStart(2,'0')+':'+String(v%60).padStart(2,'0')}}}
function isTaskFocused(t){if(!t||t.done)return false; if(state.focusIds.includes(t.id)||t.focus)return true; const base=t.seriesId||t.id; const r=state.focusRules[base]; return !!(r&&r.mode==='future'&&t.date>=r.from)}
function saveTask(id,fresh){const old=state.tasks.find(x=>x.id===id),all=document.querySelector('#eall').checked,time=all?'':document.querySelector('#etime').value;const title=document.querySelector('#etitle').value.trim();if(!title){alert('Укажи название дела.');return}if(!all&&!time){alert('Укажи время задачи или выбери «Весь день».');return}const wantsFocus=document.querySelector('#efocus').checked;const repeat=document.querySelector('#erepeat').value;const oldSeriesId=old?.seriesId||null;const oldWasRepeating=!!(old&&old.repeat&&old.repeat!=='Не повторять');if(oldWasRepeating&&repeat==='Не повторять'&&oldSeriesId){state.tasks=state.tasks.filter(x=>!(x.generated===true&&x.seriesId===oldSeriesId&&x.id!==old.id));delete state.focusRules[oldSeriesId];state.tasks.forEach(x=>{if((x.seriesId||x.id)===oldSeriesId)x.focus=false});state.focusIds=state.focusIds.filter(fid=>state.tasks.some(x=>x.id===fid));}const seriesId=old?.seriesId||((repeat!=='Не повторять')?uid():null);const t={id,title,date:document.querySelector('#edate').value,time,allDay:all,groupId:document.querySelector('#egroup').value,color:(old&&old.groupId!==document.querySelector('#egroup').value&&old.color===state.groups.find(g=>g.id===old.groupId)?.color)?(state.groups.find(g=>g.id===document.querySelector('#egroup').value)?.color||document.querySelector('#etcolor')?.value||''):(document.querySelector('#etcolor')?.value||''),priority:document.querySelector('#eprio').value,important:document.querySelector('#eimp').checked,repeat,interval:Number(document.querySelector('#einterval')?.value||1),unit:document.querySelector('#eunit')?.value||'days',comment:document.querySelector('#ecomment').value.trim(),reminder:document.querySelector('#erem').checked,reminderSound:(document.querySelector('#ersound')?.value||'sound')==='sound',reminderOffset:document.querySelector('#eremoffset')?.value||'manual',reminderTime:document.querySelector('#eremtime')?.value||'',sound:document.querySelector('#esound')?.value||state.settings.defaultSound,done:old?.done||false,seriesId,focus:wantsFocus,generated:old?.generated===true,generatedFrom:old?.generatedFrom||null};if(fresh)state.tasks.push(t);else Object.assign(old,t);const base=t.seriesId||t.id;const mode=document.querySelector('input[name=focusMode]:checked')?.value||'single';if(wantsFocus&&repeat!=='Не повторять'){applySeriesFocusInline(t,mode);}else if(wantsFocus){t.focus=true;if(!state.focusIds.includes(t.id))state.focusIds.push(t.id);}else{t.focus=false;state.focusIds=state.focusIds.filter(x=>x!==t.id);if(base&&state.focusRules[base]){delete state.focusRules[base];state.tasks.forEach(x=>{if((x.seriesId||x.id)===base)x.focus=false;});state.focusIds=state.focusIds.filter(fid=>{const ft=state.tasks.find(x=>x.id===fid);return !ft||((ft.seriesId||ft.id)!==base)});}}if(t.reminder)requestReminderPermission();if(t.repeat!=='Не повторять'){if(t.generated)syncEditedInstance(t);else syncSeriesFuture(t,30);}save();closeModal();app()}
function nextDate(t,from){let d=parseDate(from);if(t.repeat==='Каждые 5 минут')d.setMinutes(d.getMinutes()+5);else if(t.repeat==='Каждые 15 минут')d.setMinutes(d.getMinutes()+15);else if(t.repeat==='Каждые 30 минут')d.setMinutes(d.getMinutes()+30);else if(t.repeat==='Каждый час')d.setHours(d.getHours()+1);else if(t.repeat==='Каждый день')d.setDate(d.getDate()+1);else if(t.repeat==='Каждую неделю')d.setDate(d.getDate()+7);else if(t.repeat==='Каждый месяц')d.setMonth(d.getMonth()+1);else if(t.repeat==='Каждый год')d.setFullYear(d.getFullYear()+1);else if(t.repeat==='Произвольный интервал'){if(t.unit==='minutes')d.setMinutes(d.getMinutes()+t.interval);if(t.unit==='hours')d.setHours(d.getHours()+t.interval);if(t.unit==='days')d.setDate(d.getDate()+t.interval);if(t.unit==='weeks')d.setDate(d.getDate()+7*t.interval);if(t.unit==='months')d.setMonth(d.getMonth()+t.interval)}return iso(d)}
function findSeriesRoot(series){const base=series.seriesId||series.id;return state.tasks.filter(x=>(x.seriesId||x.id)===base&&x.generated!==true).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time))[0]||series}
function copySeriesFields(src,dst){dst.title=src.title;dst.time=src.time;dst.allDay=src.allDay;dst.groupId=src.groupId;dst.priority=src.priority;dst.important=src.important;dst.repeat=src.repeat;dst.interval=src.interval;dst.unit=src.unit;dst.comment=src.comment;dst.reminder=src.reminder;dst.reminderSound=src.reminderSound;dst.reminderOffset=src.reminderOffset;dst.reminderTime=src.reminderTime;dst.sound=src.sound;dst.seriesId=src.seriesId;dst.generated=true;dst.generatedFrom=src.id;}
function syncSeriesFuture(series,days=30){const base=series.seriesId||series.id;let root=state.tasks.find(x=>x.id===series.id&&x.generated!==true)||findSeriesRoot(series);if(root!==series&&series.generated!==true)Object.assign(root,{title:series.title,date:series.date,time:series.time,allDay:series.allDay,groupId:series.groupId,color:series.color,priority:series.priority,important:series.important,repeat:series.repeat,interval:series.interval,unit:series.unit,comment:series.comment,reminder:series.reminder,reminderSound:series.reminderSound,reminderOffset:series.reminderOffset,reminderTime:series.reminderTime,sound:series.sound,focus:series.focus});const canonicalBase=root.seriesId||base||root.id;root.seriesId=canonicalBase;const seriesBase=canonicalBase;const doneDates=new Set(state.tasks.filter(x=>x.generated===true&&x.seriesId===seriesBase&&x.done).map(x=>x.date));state.tasks=state.tasks.filter(x=>!(x.generated===true&&x.seriesId===seriesBase&&!x.done));let cur=root.date;for(let i=0;i<days;i++){cur=nextDate(root,cur);if(!cur)break;if(doneDates.has(cur))continue;const clone={...root,id:uid(),date:cur,done:false,generated:true,generatedFrom:root.id,focus:!!(state.focusRules[seriesBase]?.mode==='future'&&cur>=state.focusRules[seriesBase].from)};state.tasks.push(clone)}state.tasks.forEach(x=>{if(x.seriesId===seriesBase&&x.generated===true&&x.done)x.focus=false})}
function syncEditedInstance(instance){const base=instance.seriesId;if(!base)return;const collision=state.tasks.find(x=>x.id!==instance.id&&x.generated===true&&x.seriesId===base&&x.date===instance.date);if(collision){state.tasks=state.tasks.filter(x=>x.id!==collision.id)}instance.generated=true;instance.generatedFrom=instance.generatedFrom||base;}
function ensureFutureInstances(series,days=30){const root=findSeriesRoot(series);const base=root.seriesId||root.id;root.seriesId=base;const seen=new Set();const cleaned=[];for(const x of state.tasks){if(x.generated===true&&x.seriesId===base){if(seen.has(x.date))continue;seen.add(x.date)}cleaned.push(x)}state.tasks=cleaned;let cur=root.date;for(let i=0;i<days;i++){cur=nextDate(root,cur);if(!cur)break;const exists=state.tasks.some(x=>x.generated===true&&x.seriesId===base&&x.date===cur);if(!exists)state.tasks.push({...root,id:uid(),date:cur,done:false,generated:true,generatedFrom:root.id,focus:!!(state.focusRules[base]?.mode==='future'&&cur>=state.focusRules[base].from)})}}
function toggle(id){const t=state.tasks.find(x=>x.id===id);if(!t)return;t.done=!t.done;let praised=false;if(t.done){state.events=state.events.filter(e=>!(e.taskId===id&&e.date===t.date));state.events.push({id:uid(),taskId:id,seriesId:t.seriesId||id,title:t.title,date:t.date,at:new Date().toISOString(),completed:true});state.focusIds=state.focusIds.filter(x=>x!==id);if(t.repeat!=='Не повторять')ensureFutureInstances(t,30);praised=true}else{state.events=state.events.filter(e=>!(e.taskId===id&&e.date===t.date))}save();app();if(praised)showPraise()}
function showPraise(){const e=document.querySelector('#praise');if(!e)return;clearTimeout(window.__praiseTimer);e.innerHTML=`<div class="praise-backdrop"><div class="praise"><button class="praise-close" aria-label="Закрыть" onclick="document.querySelector('#praise').innerHTML=''">✕</button><div class="praise-icon">✦</div><div class="praise-title">${praise[Math.floor(Math.random()*praise.length)]}</div><div class="praise-sub">Ещё один шаг выполнен. Так держать! 💛</div><button class="primary" onclick="document.querySelector('#praise').innerHTML=''">Продолжать в том же духе</button></div></div>`;window.__praiseTimer=setTimeout(()=>{if(e)e.innerHTML=''},15000)}
function delTask(id){const t=state.tasks.find(x=>x.id===id);if(!t)return;state.tasks=state.tasks.filter(x=>x.id!==id);state.events=state.events.filter(e=>e.taskId!==id);state.focusIds=state.focusIds.filter(x=>x!==id);save();closeModal();app()}
function quickDeleteTask(id){const t=state.tasks.find(x=>x.id===id);if(!t)return;if(t.repeat&&t.repeat!=='Не повторять'&&t.seriesId){modal(`<div class="between"><h2>Удалить повтор</h2><button onclick="closeModal()">✕</button></div><p>Как удалить «${esc(t.title)}»?</p><div class="toolbar"><button class="danger" onclick="deleteSeriesFrom('${t.id}',false)">Только эту задачу</button><button class="danger" onclick="deleteSeriesFrom('${t.id}',true)">Эту и все будущие повторы</button></div>`)}else if(confirm(`Удалить «${t.title}»?`)){delTask(id)}}
function deleteSeriesFrom(id,future){const t=state.tasks.find(x=>x.id===id);if(!t){closeModal();return}const ids=future&&t.seriesId?state.tasks.filter(x=>x.seriesId===t.seriesId&&x.date>=t.date).map(x=>x.id):[id];if(future&&t.seriesId){state.tasks=state.tasks.filter(x=>!(x.seriesId===t.seriesId&&x.date>=t.date));}else{state.tasks=state.tasks.filter(x=>x.id!==id)}state.events=state.events.filter(e=>!ids.includes(e.taskId));state.focusIds=state.focusIds.filter(fid=>state.tasks.some(x=>x.id===fid));save();closeModal();app()}
function clearAllTasks(){if(!state.tasks.length){alert('Задач для удаления нет.');return}if(confirm(`Удалить все ${state.tasks.length} задач и их историю выполнения?

Статистика и достижения будут очищены.`)){state.tasks=[];state.events=[];state.focusIds=[];state.focusRules={};save();app()}}
function clearEverything(){if(confirm('Полностью очистить MyPlanner?\n\nБудут удалены задачи, история выполнений, статистика, достижения и данные Фокуса. Заметки, фон, группы и настройки останутся.')){state.tasks=[];state.events=[];state.focusIds=[];state.focusRules={};state.statsPeriod='today';delete state.statsFrom;delete state.statsTo;save();app()}}
function roulette(){const items=state.tasks.filter(t=>t.allDay&&!t.done);const colors=['#f4b6c2','#f9d5a7','#b9dcd5','#c6c4ef','#f5c5a8','#e7b7d0','#b9d5ee','#e8d8a8'];const n=items.length;const step=n?360/n:0;const stops=items.map((_,i)=>`${colors[i%colors.length]} ${i*100/n}% ${((i+1)*100/n)}%`).join(',');const labelSize=Math.max(6,Math.min(12,Math.round(150/Math.max(n,1))));return `<section class="card"><div class="between"><div><h2>🎡 Рулетка дел</h2><div class="small">Случайно выбираем, с чего начать. Здесь только незавершённые задачи «Весь день».</div></div><b>${n} дел</b></div>${n?`<div class="roulette-wrap"><div class="roulette-pointer">▼</div><div id="rouletteWheel" class="roulette-wheel" style="--sectors:${n};--wheel-gradient:conic-gradient(from ${-step/2}deg,${stops});--sector-angle:${step}deg">${items.map((t,i)=>`<div class="roulette-sector" style="--angle:${i*step-step/2}deg;--label-size:${labelSize}px"><span>${esc(t.title)}</span></div>`).join('')}</div></div><div id="rouletteResult" class="roulette-result">Нажми «Старт», чтобы выбрать дело.</div><button id="rouletteStart" class="primary roulette-start" onclick="startRoulette()">▶ Старт</button>`:'<div class="empty">Нет незавершённых задач на весь день. Добавь такую задачу — и она появится здесь.</div>'}</section>`}
let rouletteTimer=null;function startRoulette(){const items=state.tasks.filter(t=>t.allDay&&!t.done);if(!items.length)return;const btn=document.querySelector('#rouletteStart'),wheel=document.querySelector('#rouletteWheel'),out=document.querySelector('#rouletteResult');if(!wheel||!btn)return;btn.disabled=true;out.textContent='Крутим…';const winner=items[Math.floor(Math.random()*items.length)],duration=5000+Math.floor(Math.random()*5001);wheel.style.transition=`transform ${duration}ms cubic-bezier(.12,.72,.16,1)`;const idx=items.findIndex(t=>t.id===winner.id),angle=360*5-(idx*360/items.length);wheel.style.transform=`rotate(${angle}deg)`;rouletteTimer=setTimeout(()=>{out.innerHTML=`Выпало дело: <b>${esc(winner.title)}</b>`;btn.disabled=false;btn.textContent='↻ Крутить ещё раз';},duration)}
function focus(){const today=iso(new Date()), horizon=Number(state.settings.focusHorizon||3), rules=state.focusRules;let dates=[];for(let i=0;i<horizon;i++){let d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()+i);dates.push(iso(d))}const limit=Number(state.settings.focusLimit??3);const focusedTasks=sortTasks(state.tasks.filter(t=>dates.includes(t.date)&&isTaskFocused(t)));const chosen=focusedTasks;return `${sortControl()}<section class="card"><div class="between"><div><h2>🎯 Фокус</h2></div><button class="primary" onclick="editFocus()">Настроить</button></div><div class="toolbar"><button class="${horizon===1?'primary':''}" onclick="setFocusHorizon(1)">Сегодня</button><button class="${horizon===3?'primary':''}" onclick="setFocusHorizon(3)">3 дня</button><button class="${horizon===7?'primary':''}" onclick="setFocusHorizon(7)">Неделя</button></div></section>${dates.map((s,i)=>{const ts=chosen.filter(t=>t.date===s);return `<section class="card"><div class="between"><b>${i===0?'Сегодня':i===1?'Завтра':fmtDate(s)}</b><span class="small">${ts.length} дел</span></div>${sortTasks(ts).map(t=>taskCard(t,true)).join('')||'<div class="small">Фокус на этот день пока пуст.</div>'}</section>`}).join('')}`}
function setFocusHorizon(n){state.settings.focusHorizon=n;save();app()}
function toggleFocusChoice(){const box=document.querySelector('#focusChoice');const cb=document.querySelector('#efocus');const rep=document.querySelector('#erepeat')?.value;if(box)box.style.display=(cb?.checked&&rep!=='Не повторять')?'block':'none';}
function applySeriesFocusInline(t,mode){const base=t.seriesId||t.id;if(mode==='future'){state.focusRules[base]={mode:'future',from:t.date};state.tasks.forEach(x=>{if((x.seriesId||x.id)===base&&x.date>=t.date&&!x.done){x.focus=true;if(!state.focusIds.includes(x.id))state.focusIds.push(x.id)}})}else{state.focusRules[base]={mode:'single',from:t.date};state.tasks.forEach(x=>{if((x.seriesId||x.id)===base)x.focus=false});t.focus=true;if(!state.focusIds.includes(t.id))state.focusIds.push(t.id)}}
function chooseSeriesFocus(id){const t=state.tasks.find(x=>x.id===id);if(!t||!t.seriesId)return;modal(`<div class="between"><h2>🎯 Фокус для повторения</h2><button onclick="closeModal()">✕</button></div><p>Это повторяющаяся задача. Добавить в Фокус только сегодняшний экземпляр или всю серию?</p><div class="toolbar"><button class="primary" onclick="applySeriesFocus('${id}','single')">Только эту задачу</button><button onclick="applySeriesFocus('${id}','future')">Эту и все будущие повторы</button></div>`)}
function applySeriesFocus(id,mode){const t=state.tasks.find(x=>x.id===id);if(!t)return;const base=t.seriesId||t.id;if(mode==='future'){state.tasks.forEach(x=>{if((x.seriesId||x.id)===base&&x.date>=t.date&&!x.done){x.focus=true;if(!state.focusIds.includes(x.id))state.focusIds.push(x.id)}});state.focusRules[base]={mode:'future',from:t.date}}else{t.focus=true;if(!state.focusIds.includes(t.id))state.focusIds.push(t.id);state.focusRules[base]={mode:'single',from:t.date}}save();closeModal();app()}
function editFocus(){const sel=new Set(state.focusIds),h=Number(state.settings.focusHorizon||3);modal(`<div class="between"><h2>🎯 Настройка Фокуса</h2><button onclick="closeModal()">✕</button></div><p class="small">Можно выбрать конкретные экземпляры или включить всю серию повторяющейся задачи.</p><div class="field"><label>Горизонт</label><select id="fh" class="input"><option value="1" ${h===1?'selected':''}>Сегодня</option><option value="3" ${h===3?'selected':''}>3 дня</option><option value="7" ${h===7?'selected':''}>Неделя</option></select></div><div class="focus-list">${state.tasks.filter(t=>!t.done).slice().sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map(t=>`<label class="focus-option"><input type="checkbox" value="${t.id}" ${sel.has(t.id)||t.focus?'checked':''}> <span><b>${esc(t.title)}</b><small>📅 ${fmtDate(t.date)} · ${t.allDay?'Весь день':t.time}</small></span></label>`).join('')||'<div class="empty">Нет активных дел.</div>'}</div><button class="primary" onclick="saveFocus()">Сохранить</button>`)}
function saveFocus(){state.settings.focusHorizon=Number(document.querySelector('#fh').value);const ids=[...document.querySelectorAll('.focus-option input:checked')].map(x=>x.value);state.focusIds=ids;state.tasks.forEach(t=>t.focus=ids.includes(t.id));save();closeModal();app()}
function stats(){const now=new Date();let from,to;const p=state.statsPeriod;if(p==='today'){from=iso(now);to=from}else if(p==='week'){let d=new Date(now);d.setDate(d.getDate()-6);from=iso(d);to=iso(now)}else if(p==='month'){let y=now.getFullYear(),m=now.getMonth()-1,day=now.getDate();let prevLast=new Date(y,m+1,0).getDate();let start=new Date(y,m,Math.min(day,prevLast));from=iso(start);to=iso(now)}else{from=state.statsFrom||iso(new Date(now.getFullYear(),now.getMonth(),1));to=state.statsTo||iso(now)}const events=state.events.filter(e=>e.date>=from&&e.date<=to);const current=state.tasks.filter(t=>t.date>=from&&t.date<=to);const doneCurrent=current.filter(t=>t.done).length;const total=current.length;const eventKeys=new Set();events.forEach(e=>eventKeys.add((e.taskId||e.id)+'|'+e.date));const completionCount=Math.max(eventKeys.size,doneCurrent);let by={};events.forEach(e=>by[e.title]=(by[e.title]||0)+1);current.filter(t=>t.done&&!events.some(e=>e.taskId===t.id&&e.date===t.date)).forEach(t=>by[t.title]=(by[t.title]||0)+1);return `<section class="card"><div class="between"><h2>📊 Статистика</h2><select class="input" style="max-width:180px" onchange="state.statsPeriod=this.value;save();app()"><option value="today" ${p==='today'?'selected':''}>Сегодня</option><option value="week" ${p==='week'?'selected':''}>Неделя</option><option value="month" ${p==='month'?'selected':''}>Месяц</option><option value="custom" ${p==='custom'?'selected':''}>Произвольный период</option></select></div>${p==='custom'?`<div class="grid"><input class="input" type="date" value="${from}" onchange="state.statsFrom=this.value;save();app()"><input class="input" type="date" value="${to}" onchange="state.statsTo=this.value;save();app()"></div>`:''}</section><section class="grid"><div class="card"><div class="stats">${total}</div><div class="small">Дел</div></div><div class="card"><div class="stats">${completionCount}</div><div class="small">Выполнений</div></div><div class="card"><div class="stats">${total?Math.round(doneCurrent/total*100):0}%</div><div class="small">Выполнено за период</div></div><div class="card"><div class="stats">${streak()}</div><div class="small">Дней серии</div></div></section><section class="card"><h3>По названию</h3>${Object.entries(by).sort((a,b)=>b[1]-a[1]).map(x=>`<div class="between"><span>${esc(x[0])}</span><b>${x[1]}</b></div>`).join('')||'<p class="small">За выбранный период выполнений нет.</p>'}</section><section class="card"><h3>🏆 Достижения</h3>${achievements().map(x=>`<p>${x}</p>`).join('')}</section>`}
function streak(){const dates=new Set(state.events.map(e=>e.date));let d=new Date();let s=0;while(dates.has(iso(d))){s++;d.setDate(d.getDate()-1)}return s}
function achievements(){const n=state.events.length,s=streak();return [`${n>=1?'🥇':'🔒'} Первое выполнение`,`${n>=10?'🏆':'🔒'} 10 выполнений`,`${n>=50?'🏆':'🔒'} 50 выполнений`,`${s>=3?'🔥':'🔒'} Серия 3 дня`,`${s>=7?'🔥':'🔒'} Серия 7 дней`]}
function notes(){
 const sorted=state.notes.slice().sort((a,b)=>noteCompare(a,b,state.noteSort||'new'));
 return `<section class="card"><div class="between"><div><h2>📝 Заметки</h2><div class="small">Заметки работают как папки: внутри можно создавать вложенные папки, документы, фото и файлы.</div></div><button class="primary" onclick="newNote()">+ Папка</button></div><div class="toolbar note-toolbar"><select class="input" style="max-width:230px" onchange="state.noteSort=this.value;save();app()"><option value="new" ${(state.noteSort||'new')==='new'?'selected':''}>Сначала новые</option><option value="old" ${state.noteSort==='old'?'selected':''}>Сначала старые</option><option value="az" ${state.noteSort==='az'?'selected':''}>По названию А–Я</option><option value="za" ${state.noteSort==='za'?'selected':''}>По названию Я–А</option></select></div></section>${sorted.map(noteFolderCard).join('')||'<div class="empty">Заметок пока нет.<br>Нажми «+ Папка».</div>'}`
}
function noteCompare(a,b,mode){
 if(mode==='az')return String(a.title||'').localeCompare(String(b.title||''),'ru');
 if(mode==='za')return String(b.title||'').localeCompare(String(a.title||''),'ru');
 const ad=Date.parse(a.updated||a.created||0)||0,bd=Date.parse(b.updated||b.created||0)||0;
 return mode==='old'?ad-bd:bd-ad;
}
function noteFolderCard(n){
 const items=Array.isArray(n.items)?n.items:[];
 const folders=items.filter(x=>x.type==='section').length;
 const files=items.filter(x=>x.type==='file').length;
 const texts=items.filter(x=>x.type==='text').length;
 const content=items.length?items.map(it=>renderNoteEntry(it,n.id)).join(''):'<div class="small note-empty">Папка пока пуста. Добавь текст, вложенную папку, фото или файл.</div>';
 return `<section class="card note-folder"><details class="top-note-disclosure" data-note-key="${n.id}"><summary><div class="folder-row"><span class="folder-arrow" aria-hidden="true">›</span><div class="big-folder">📁</div><div class="grow"><h3>${esc(n.title)}</h3><div class="small">${folders} папок · ${files} файлов · ${texts} записей</div></div><div class="small note-created">Создана: ${new Date(n.created||n.updated||Date.now()).toLocaleDateString('ru-RU')}</div><button class="note-trash" aria-label="Удалить папку" title="Удалить папку" onclick="event.preventDefault();event.stopPropagation();if(confirm('Удалить эту папку и всё её содержимое? Это действие нельзя отменить.'))delNote('${n.id}')">🗑</button></div></summary><div class="top-note-content"><div class="note-entry-list">${content}</div><button class="primary note-add-button" onclick="addNoteItem('${n.id}')">＋ Добавить в папку</button></div></details></section>`
}
function openNote(id){state.noteOpen=id;state.notePath=[];app()}
function closeNote(){state.noteOpen=null;state.notePath=[];app()}
function getNoteItem(n,id){if(!id)return n;let found=null;function walk(items){for(const x of items||[]){if(x.id===id){found=x;return true}if(x.items&&walk(x.items))return true}return false}walk(n.items);return found}
function currentNoteContainer(n){return state.notePath.length?getNoteItem(n,state.notePath[state.notePath.length-1])?.items||[]:n.items||[]}
function noteContainerTitle(n){if(!state.notePath.length)return n.title;const x=getNoteItem(n,state.notePath[state.notePath.length-1]);return x?.text||n.title}
function noteContentCompare(a,b,mode){
 const name=x=>String(x.type==='section'?x.text:(x.name||x.text||''));
 if(mode==='az')return name(a).localeCompare(name(b),'ru');
 if(mode==='za')return name(b).localeCompare(name(a),'ru');
 if(mode==='files')return (a.type==='file'?0:1)-(b.type==='file'?0:1)||((Date.parse(b.created||0)||0)-(Date.parse(a.created||0)||0));
 if(mode==='text')return (a.type==='text'?0:1)-(b.type==='text'?0:1)||((Date.parse(b.created||0)||0)-(Date.parse(a.created||0)||0));
 const ad=Date.parse(a.created||0)||0,bd=Date.parse(b.created||0)||0;return mode==='old'?ad-bd:bd-ad;
}
function noteBrowser(){
 const n=state.notes.find(x=>x.id===state.noteOpen);if(!n){state.noteOpen=null;state.notePath=[];return notes()}
 const items=currentNoteContainer(n).slice().sort((a,b)=>noteContentCompare(a,b,state.noteSortItems||'new'));
 const inRoot=!state.notePath.length;
 const parent=state.notePath.length>1?state.notePath[state.notePath.length-2]:null;
 return `<section class="card note-browser-head"><div class="between"><button onclick="${inRoot?'closeNote()':'state.notePath.pop();app()'}">← Назад</button><div class="folder-title"><span>📁</span><b>${esc(noteContainerTitle(n))}</b></div><button onclick="addNoteItem('${n.id}',${state.notePath.length?`'${state.notePath[state.notePath.length-1]}'`:'null'})">＋</button></div><div class="toolbar"><select class="input" style="max-width:230px" onchange="state.noteSortItems=this.value;save();app()"><option value="new" ${(state.noteSortItems||'new')==='new'?'selected':''}>Сначала новые</option><option value="old" ${state.noteSortItems==='old'?'selected':''}>Сначала старые</option><option value="az" ${state.noteSortItems==='az'?'selected':''}>По названию А–Я</option><option value="za" ${state.noteSortItems==='za'?'selected':''}>По названию Я–А</option><option value="files" ${state.noteSortItems==='files'?'selected':''}>Сначала файлы</option><option value="text" ${state.noteSortItems==='text'?'selected':''}>Сначала текст</option></select></div></section>${items.length?`<section class="card folder-list">${items.map(it=>renderNoteEntry(it,n.id)).join('')}</section>`:'<div class="empty">Папка пуста.<br>Добавь сюда папку, текст, фото или файл.</div>'}`
}
function renderNoteEntry(it,nid){
 if(it.type==='section')return `<details class="file-row folder-entry inline-note-section" data-note-key="${it.id}"><summary><span class="entry-icon">📁</span><span class="grow"><b>${esc(it.text)}</b><small>${(it.items||[]).length} элементов</small></span><button class="note-trash" aria-label="Удалить папку" title="Удалить папку" onclick="event.preventDefault();event.stopPropagation();deleteNoteItem('${nid}','${it.id}')">🗑</button></summary><div class="inline-note-contents">${(it.items||[]).map(child=>renderNoteEntry(child,nid)).join('')||'<small>Папка пуста</small>'}<button class="note-add-button" onclick="addNoteItem('${nid}','${it.id}')">＋ Добавить сюда</button></div></details>`;
 if(it.type==='file'){
  const isImg=(it.mime||'').startsWith('image/');
  return `<div class="file-row file-entry"><button class="file-open" onclick="openNoteFile('${nid}','${it.id}')"><span class="entry-icon">${isImg?'🖼️':'📄'}</span><span class="grow"><b>${esc(it.name||'Файл')}</b><small>${new Date(it.created||Date.now()).toLocaleString('ru-RU')}</small></span></button><button class="note-trash" aria-label="Удалить элемент" title="Удалить элемент" onclick="deleteNoteItem('${nid}','${it.id}')">🗑</button></div>`
 }
 return `<div class="file-row text-entry"><span class="entry-icon">💬</span><span class="grow"><b>${esc((it.text||'').slice(0,120))}${(it.text||'').length>120?'…':''}</b><small>${new Date(it.created||Date.now()).toLocaleString('ru-RU')}</small></span><button class="note-trash" aria-label="Удалить элемент" title="Удалить элемент" onclick="deleteNoteItem('${nid}','${it.id}')">🗑</button></div>`
}
function openNoteFile(nid,id){
 const n=state.notes.find(x=>x.id===nid),it=getNoteItem(n,id);if(!it)return;
 const isImg=(it.mime||'').startsWith('image/');
 const media=isImg?`<div class="full-file-view image-viewer"><img src="${it.data}" alt="${esc(it.name||'Фото')}"></div>`:`<div class="full-file-view"><iframe src="${it.data}" title="${esc(it.name||'Файл')}"></iframe></div>`;
 modal(`<div class="file-modal"><div class="between file-view-head"><h2>${isImg?'Фото':'Файл'}</h2><button onclick="closeModal()">✕</button></div>${media}<div class="toolbar file-actions"><button class="primary" onclick="shareNoteFile('${nid}','${id}')">Поделиться</button><button onclick="closeModal()">Закрыть</button></div></div>`);
}
function openNoteFileNew(nid,id){openNoteFile(nid,id)}
async function shareNoteFile(nid,id){const n=state.notes.find(x=>x.id===nid),it=getNoteItem(n,id);if(!it?.data)return;try{const res=await fetch(it.data),blob=await res.blob(),file=new File([blob],it.name||'MyPlanner-файл',{type:it.mime||blob.type||'application/octet-stream'});if(navigator.share&&(!navigator.canShare||navigator.canShare({files:[file]}))){await navigator.share({title:it.name||'MyPlanner',files:[file]});}else{const a=document.createElement('a');a.href=URL.createObjectURL(file);a.download=it.name||'MyPlanner-файл';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}}catch(e){alert('Не удалось поделиться файлом. Можно открыть его отдельно и воспользоваться меню «Поделиться» iPhone.')}
}
function newNote(){modal(`<div class="between"><h2>Новая папка</h2><button onclick="closeModal()">✕</button></div><div class="field"><label>Название</label><input id="nt" class="input" placeholder="Например, Ремонт кухни"></div><div class="field"><label>Первая запись — необязательно</label><textarea id="nx" rows="4" placeholder="Можно оставить пустым и добавить содержимое позже"></textarea></div><button class="primary" onclick="saveNote()">Создать</button>`)}
function saveNote(){const title=document.querySelector('#nt').value.trim();if(!title)return;const text=document.querySelector('#nx').value.trim();state.notes.push({id:uid(),title,items:text?[{id:uid(),type:'text',text,created:new Date().toISOString()}]:[],created:new Date().toISOString(),updated:new Date().toISOString()});save();closeModal();app()}
function addNoteItem(id,parentId=null){modal(`<div class="between"><h2>Добавить в папку</h2><button onclick="closeModal()">✕</button></div><div class="toolbar note-add-grid"><button onclick="addTextItem('${id}',${parentId?`'${parentId}'`:'null'})">💬 Текст</button><button onclick="addSectionItem('${id}',${parentId?`'${parentId}'`:'null'})">📁 Новая папка</button><button onclick="document.querySelector('#nf').click()">📎 Файл / фото</button></div><input id="nf" type="file" hidden onchange="addFileItem('${id}',this.files[0],${parentId?`'${parentId}'`:'null'})"><p class="small">Фото, PDF и документы сохраняются локально внутри папки.</p>`)}
function findNoteContainer(n,parentId){if(!parentId)return n.items;function walk(items){for(const x of items||[]){if(x.id===parentId)return x.items||(x.items=[]);if(x.items){const r=walk(x.items);if(r)return r}}}return walk(n.items)||n.items}
function addTextItem(id,parentId=null){modal(`<div class="between"><h2>Новая запись</h2><button onclick="closeModal()">✕</button></div><textarea id="ni" rows="7" placeholder="Текст записи"></textarea><button class="primary" onclick="finishNoteText('${id}',${parentId?`'${parentId}'`:'null'})">Добавить</button>`)}
function finishNoteText(id,parentId=null){const v=document.querySelector('#ni').value.trim();if(!v)return;const n=state.notes.find(x=>x.id===id);findNoteContainer(n,parentId).push({id:uid(),type:'text',text:v,created:new Date().toISOString()});n.updated=new Date().toISOString();save();closeModal();app()}
function addSectionItem(id,parentId=null){modal(`<div class="between"><h2>Новая папка</h2><button onclick="closeModal()">✕</button></div><input id="ns" class="input" placeholder="Название папки"><button class="primary" onclick="finishSection('${id}',${parentId?`'${parentId}'`:'null'})">Создать</button>`)}
function finishSection(id,parentId=null){const v=document.querySelector('#ns').value.trim();if(!v)return;const n=state.notes.find(x=>x.id===id);findNoteContainer(n,parentId).push({id:uid(),type:'section',text:v,items:[],created:new Date().toISOString()});n.updated=new Date().toISOString();save();closeModal();app()}
function addSectionContent(id,parentId){addNoteItem(id,parentId)}
function addFileItem(id,file,parentId=null){if(!file)return;const r=new FileReader();r.onload=()=>{const n=state.notes.find(x=>x.id===id);findNoteContainer(n,parentId).push({id:uid(),type:'file',name:file.name,data:r.result,mime:file.type,created:new Date().toISOString()});n.updated=new Date().toISOString();save();closeModal();app()};r.readAsDataURL(file)}

function deleteNoteItem(nid,id){if(!confirm('Удалить этот элемент и его вложенное содержимое?'))return;const opened=[...document.querySelectorAll('.top-note-disclosure[open],.inline-note-section[open]')].map(e=>e.dataset.noteKey||e.querySelector(':scope > summary')?.textContent?.trim()).filter(Boolean);const n=state.notes.find(x=>x.id===nid);if(!n)return;function remove(items){const i=items.findIndex(x=>x.id===id);if(i>=0){items.splice(i,1);return true}for(const x of items){if(x.items&&remove(x.items))return true}return false}remove(n.items||[]);n.updated=new Date().toISOString();save();app();document.querySelectorAll('.top-note-disclosure,.inline-note-section').forEach(e=>{const k=e.dataset.noteKey||e.querySelector(':scope > summary')?.textContent?.trim();if(opened.includes(k))e.open=true})}
function delNote(id){state.notes=state.notes.filter(n=>n.id!==id);if(state.noteOpen===id){state.noteOpen=null;state.notePath=[]}save();app()}
async function updateApp(){
  const btn=document.querySelector('#updateBtn');
  if(btn){btn.disabled=true;btn.textContent='⏳ Обновляем…';}
  try{
    if('serviceWorker' in navigator){
      const reg=await navigator.serviceWorker.getRegistration('./');
      if(reg){
        await reg.update();
        if(reg.waiting)reg.waiting.postMessage('SKIP_WAITING');
        else if(reg.installing)await new Promise(resolve=>{const w=reg.installing;w.addEventListener('statechange',()=>{if(w.state==='installed'){if(reg.waiting)reg.waiting.postMessage('SKIP_WAITING');resolve()}})});
      }
    }
    if(btn)btn.textContent='✓ Обновлено';
    setTimeout(()=>{const u=new URL(location.href);u.searchParams.set('mp_refresh',Date.now());location.replace(u.href)},250);
  }catch(e){console.error('MyPlanner update failed',e);if(btn){btn.disabled=false;btn.textContent='🔄 Обновить MyPlanner';}alert('Не удалось обновить приложение. Попробуй обычное обновление страницы.')}
}

function settings(){return `<section class="card settings-section"><h2>⚙️ Настройки</h2><p class="small">Все дополнительные настройки собраны здесь, чтобы форма задачи оставалась простой.</p><div class="toolbar"><button id="updateBtn" class="primary" onclick="updateApp()">🔄 Обновить MyPlanner</button></div><p class="small">Обновление меняет программу, но не трогает задачи, заметки и статистику.</p></section><section class="card"><h3>👥 Группы</h3><div class="compact-groups">${state.groups.map(g=>`<div class="group-row"><span class="group-icon" style="background:${g.color}">${g.icon}</span><b>${esc(g.name)}</b><span class="grow"></span><button onclick="editGroup('${g.id}')">✎</button>${g.system?'':`<button class="danger" onclick="deleteGroup('${g.id}')">×</button>`}</div>`).join('')}</div><button class="primary" onclick="editGroup()">+ Добавить группу</button></section><section class="card"><h3>🔔 Напоминания</h3><label class="switch"><input type="checkbox" ${state.settings.sound?'checked':''} onchange="state.settings.sound=this.checked;save()"> Звуковые напоминания</label><div class="field"><label>Время напоминания по умолчанию</label><select class="input" onchange="state.settings.defaultReminderOffset=this.value;save()">${[['at','В момент дела'],['5m','За 5 минут'],['10m','За 10 минут'],['15m','За 15 минут'],['30m','За 30 минут'],['1h','За 1 час'],['2h','За 2 часа'],['1d','За 1 день']].map(x=>`<option value="${x[0]}" ${state.settings.defaultReminderOffset===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></div><div class="field"><label>Мелодия по умолчанию</label><select class="input" onchange="state.settings.defaultSound=this.value;save()">${soundOptions(state.settings.defaultSound)}</select></div><button onclick="previewSound(state.settings.defaultSound)">▶ Прослушать</button><p class="small">На iPhone через PWA звук и системные уведомления зависят от разрешений и того, открыт ли приложение. Надёжные фоновые уведомления без серверной части здесь не гарантируются.</p></section><section class="card"><h3>🎨 Оформление</h3><div class="backgrounds">${['#f5f7fb','#fff7f2','#eef8f7','#f5efff'].map(c=>`<button class="bg-swatch" style="background:${c}" onclick="setBg('solid','${c}')"></button>`).join('')}${['linear-gradient(135deg,#ffd9c8,#b8e6ff)','linear-gradient(135deg,#e8d8ff,#c9f3e4)','linear-gradient(135deg,#ffe7b8,#ffc9df)'].map((c,i)=>`<button class="bg-swatch" style="background:${c}" onclick="setBg('gradient','${encodeURIComponent(c)}')"></button>`).join('')}</div><div class="field"><label>Готовые фоны</label><select class="input" onchange="setBgPreset(this.value)"><option value="">Выбрать</option><option value="sunset">Пастельный закат</option><option value="ocean">Море и небо</option><option value="lavender">Лавандовое утро</option></select></div><div class="field"><label>Собственное фото</label><input type="file" accept="image/*" onchange="uploadBg(this.files[0])"></div><div class="toolbar"><button onclick="resetBg()">Сбросить фон</button></div></section><section class="card"><h3>🎯 Фокус</h3><div class="field"><label>Количество задач в Фокусе</label><select class="input" onchange="state.settings.focusLimit=this.value==='unlimited'?0:Number(this.value);save();app()"><option value="3" ${Number(state.settings.focusLimit??3)===3?'selected':''}>3 задачи</option><option value="5" ${Number(state.settings.focusLimit)===5?'selected':''}>5 задач</option><option value="7" ${Number(state.settings.focusLimit)===7?'selected':''}>7 задач</option><option value="10" ${Number(state.settings.focusLimit)===10?'selected':''}>10 задач</option><option value="unlimited" ${Number(state.settings.focusLimit)===0?'selected':''}>Без ограничения</option></select></div><div class="field"><label>Горизонт по умолчанию</label><select class="input" onchange="state.settings.focusHorizon=Number(this.value);save()"><option value="1" ${state.settings.focusHorizon===1?'selected':''}>Сегодня</option><option value="3" ${state.settings.focusHorizon===3?'selected':''}>3 дня</option><option value="7" ${state.settings.focusHorizon===7?'selected':''}>Неделя</option></select></div><div class="field"><label>Вечером показывать следующий день после</label><input class="input" type="time" value="${String(state.settings.focusPreviewHour).padStart(2,'0')}:00" onchange="state.settings.focusPreviewHour=Number(this.value.slice(0,2));save()"></div></section><section class="card"><h3>💾 Данные</h3><div class="toolbar"><button onclick="exportData()">Экспорт резервной копии</button><button onclick="document.querySelector('#importFile').click()">Импорт</button><input id="importFile" type="file" hidden accept="application/json" onchange="importData(this.files[0])"></div><button class="danger" onclick="clearAllTasks()">🗑️ Удалить все задачи и историю</button><p class="small">Удаляются задачи и связанная история. Заметки, фон и настройки остаются.</p><button class="danger" onclick="clearEverything()">🔥 Полностью очистить MyPlanner</button><p class="small">Полностью очищаются задачи, история, статистика, достижения и Фокус.</p></section>`}
function soundOptions(sel){return [['standard','Стандартная'],['soft','Мягкая'],['bell','Колокольчик'],['chime','Звонок'],['pulse','Короткий сигнал']].map(x=>`<option value="${x[0]}" ${sel===x[0]?'selected':''}>${x[1]}</option>`).join('')}
function editGroup(id){const g=id?state.groups.find(x=>x.id===id):{id:uid(),name:'',icon:'📌',color:'#6d7cff',system:false};modal(`<div class="between"><h2>${id?'Изменить группу':'Новая группа'}</h2><button onclick="closeModal()">✕</button></div><div class="field"><label>Название</label><input id="gn" class="input" value="${esc(g.name)}"></div><div class="grid"><div class="field"><label>Значок</label><input id="gi" class="input" value="${esc(g.icon)}" maxlength="4"></div><div class="field"><label>Цвет</label><input id="gc" class="input" type="color" value="${g.color}" oninput="this.nextElementSibling.style.background=this.value;this.nextElementSibling.textContent=this.value"><span class="color-preview" style="display:inline-block;padding:6px 12px;border-radius:6px;background:${g.color};color:#222">${g.color}</span></div></div><button class="primary" onclick="saveGroup('${g.id}',${!!id})">Сохранить и применить</button>`)}function saveGroup(id,exists){const name=document.querySelector('#gn').value.trim();if(!name)return;const g={id,name,icon:document.querySelector('#gi').value||'📌',color:document.querySelector('#gc').value,system:exists?state.groups.find(x=>x.id===id)?.system===true:false};if(exists)Object.assign(state.groups.find(x=>x.id===id),g);else state.groups.push(g);save();closeModal();app()}function deleteGroup(id){const g=state.groups.find(x=>x.id===id);if(!g||g.system)return;if(state.tasks.some(t=>t.groupId===id)){alert('В этой группе есть задачи. Сначала перенеси их в другую группу.');return}state.groups=state.groups.filter(x=>x.id!==id);save();app()}
function setBg(type,value){state.settings.background={type,value:type==='gradient'?decodeURIComponent(value):value};save();app()}function setBgPreset(v){const p={sunset:'linear-gradient(135deg,#ffd3c4,#aee5ff)',ocean:'linear-gradient(135deg,#bde8ff,#b8d7ff)',lavender:'linear-gradient(135deg,#e8d7ff,#d8f1ff)'}[v];if(p)setBg('gradient',encodeURIComponent(p))}function uploadBg(file){if(!file)return;const r=new FileReader();r.onload=()=>{state.settings.background={type:'image',value:r.result};save();app()};r.readAsDataURL(file)}function resetBg(){state.settings.background=defaultSettings.background;save();app()}function applyBackground(){const b=state.settings.background||defaultSettings.background;let v='';if(b.type==='image')v=`url(${b.value}) center/cover fixed`;else if(b.type==='gradient')v=b.value;else v=b.value;document.documentElement.style.setProperty('--app-bg',v)}
function quick(){modal(`<div class="between"><h2>Быстрое дело</h2><button onclick="closeModal()">✕</button></div><input id="q" class="input" placeholder="18:30 Позвонить маме"><button class="primary" onclick="saveQuick()">Добавить</button>`)}function saveQuick(){const s=document.querySelector('#q').value.trim(),m=s.match(/^(\d{1,2}:\d{2})\s+(.+)$/);if(!s)return;const t=baseTask();t.time=m?m[1]:'';t.title=m?m[2]:s;if(!t.time){t.allDay=true}else if(!t.time)return;state.tasks.push(t);save();closeModal();app()}
function displayReminderTime(t){const d=reminderDateTime(t);return d?'· '+d.toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}):''}
function reminderDateTime(t){if(!t.reminder||!t.date)return null;let baseTime=t.time||t.reminderTime||'09:00',base=new Date(t.date+'T'+baseTime+':00');if(Number.isNaN(base.getTime()))return null;const off=t.reminderOffset||'manual';if(off==='manual'||off==='alltime'||off.startsWith('all'))return t.reminderTime?new Date(t.date+'T'+t.reminderTime+':00'):null;if(off==='at')return base;const mins={'5m':5,'10m':10,'15m':15,'30m':30,'1h':60,'2h':120,'1d':1440}[off];if(mins==null)return null;base.setMinutes(base.getMinutes()-mins);return base}
let reminderWatcher=null;function showReminderBanner(t,rd){const host=document.querySelector('#praise')||document.body,box=document.createElement('div');box.className='praise-backdrop';box.innerHTML=`<div class="reminder-modal"><div class="praise-icon">🔔</div><b>${esc(t.title)}</b><div class="small">Напоминание · ${rd.toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}</div><button onclick="this.closest('.praise-backdrop').remove()">Закрыть</button></div>`;host.appendChild(box);if(navigator.vibrate)try{navigator.vibrate([180,100,180])}catch(e){}setTimeout(()=>box.remove(),60000)}function fireReminder(t,rd){const key='mp_rem_seen_'+t.id+'_'+rd.getTime();if(localStorage.getItem(key)==='1')return;localStorage.setItem(key,'1');showReminderBanner(t,rd);if(t.reminderSound&&state.settings.sound)previewSound(t.sound);if('Notification'in window&&Notification.permission==='granted'){try{new Notification('MyPlanner',{body:t.title,tag:key})}catch(e){}}}function requestReminderPermission(){if(!('Notification'in window))return;if(Notification.permission==='default')Notification.requestPermission().catch(()=>{})}function checkReminders(){const now=Date.now();state.tasks.forEach(t=>{if(t.reminder&&!t.done){const rd=reminderDateTime(t);if(rd){const diff=now-rd.getTime();if(diff>=0&&diff<120000)fireReminder(t,rd)}}})}function startReminderWatcher(){if(reminderWatcher)return;checkReminders();reminderWatcher=setInterval(checkReminders,5000)}
async function previewSound(type='standard'){try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return false;const c=new AC();if(c.state==='suspended')await c.resume();const p={standard:[[660,.18],[830,.22]],soft:[[440,.32],[554,.32]],bell:[[880,.18],[1175,.3],[880,.18]],chime:[[523,.18],[659,.18],[784,.32]],pulse:[[740,.12],[0,.1],[740,.12]]}[type]||[[660,.18],[830,.22]];let tt=c.currentTime+.02;p.forEach(([f,d])=>{if(f){const o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.setValueAtTime(f,tt);g.gain.setValueAtTime(.0001,tt);g.gain.linearRampToValueAtTime(.22,tt+.025);g.gain.linearRampToValueAtTime(.0001,tt+d);o.connect(g);g.connect(c.destination);o.start(tt);o.stop(tt+d+.02)}tt+=d});setTimeout(()=>c.close().catch(()=>{}),1000);return true}catch(e){return false}}
function exportData(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state)],{type:'application/json'}));a.download='MyPlanner-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}function importData(file){if(!file)return;const r=new FileReader();r.onload=()=>{try{const x=JSON.parse(r.result);if(!x||!Array.isArray(x.tasks))throw 0;state={...state,...x,settings:{...defaultSettings,...(x.settings||{})}};save();app();alert('Резервная копия восстановлена.')}catch(e){alert('Не удалось прочитать резервную копию.')}};r.readAsText(file)}
function modal(html){document.querySelector('.modal')?.remove();const d=document.createElement('div');d.className='modal';d.innerHTML=`<div class="modal-card">${html}</div>`;document.body.append(d)}function closeModal(){document.querySelector('.modal')?.remove()}
Object.assign(window,{setView,shift,monthShift,editTask,saveTask,toggle,delTask,quick,saveQuick,editFocus,saveFocus,setFocusHorizon,chooseSeriesFocus,applySeriesFocus,toggleFocusChoice,newNote,saveNote,addNoteItem,addTextItem,finishNoteText,addSectionItem,finishSection,addSectionContent,addFileItem,delNote,editGroup,saveGroup,deleteGroup,toggleAllDay,toggleRepeatFields,toggleReminderFields,toggleReminderTime,setReminderOptions,previewSound,closeModal,setBg,setBgPreset,uploadBg,resetBg,exportData,importData,updateApp,clearAllTasks,clearEverything});
save();app();
